const item = $input.first().json || {};
const transcript = String(item.transcript_text || '').trim();
const message = String(item.message || '').trim();
const meetingUrl = String(item.meeting_url || '').trim();
const turns = transcript.split(/\n+/).map(s => s.trim()).filter(Boolean);
const looksLikeMeeting = turns.length >= 5 && /(:|speaker|hablante|vinicio|lev|meeting|reunion|reunión|acuerdo|tarea|decision|decisión)/i.test(transcript);
let request_type = 'conversation';
let status_hint = 'pending';
if (transcript && looksLikeMeeting) {
  request_type = 'transcript_processing';
  status_hint = 'ready';
} else if (meetingUrl) {
  request_type = 'meeting_url_pending_transcript';
  status_hint = 'pending';
} else if (transcript) {
  request_type = 'invalid_transcript';
  status_hint = 'skipped';
}
const language = /[áéíóúñ¿¡]|\b(hola|reunion|reunión|tarea|acuerdo|correo)\b/i.test(message + ' ' + transcript) ? 'es-CR' : 'en';
return [{ json: { ...item, request_type, status_hint, language, transcript_turn_count: turns.length, transcript_valid: request_type === 'transcript_processing' } }];

const raw = $input.first().json || {};
const rawOutput = raw.output || raw.text || raw.message || raw;
let parsed = null;
if (typeof rawOutput === 'string') {
  const match = rawOutput.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch (e) { parsed = null; } }
} else if (typeof rawOutput === 'object') parsed = rawOutput;
const input = $('Classify Request').item.json || {};
const safe = parsed || {};
return [{ json: { ...input, extraction: safe, raw_extraction_output: rawOutput } }];

