const rawOutput = raw.output || raw.text || raw.message || raw;
let parsed = null;
if (typeof rawOutput === 'string') {
  const match = rawOutput.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch (e) { parsed = null; } }
} else if (typeof rawOutput === 'object') parsed = rawOutput;
const prior = $('Parse Extraction JSON').item.json || {};
const safe = parsed || {};
return [{ json: { ...prior, artifacts: safe, raw_artifact_output: rawOutput } }];

const raw = $input.first().json || {};
const rawOutput = raw.output || raw.text || raw.message || raw;
let parsed = null;
if (typeof rawOutput === 'string') {
  const match = rawOutput.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch (e) { parsed = null; } }
} else if (typeof rawOutput === 'object') parsed = rawOutput;
let base = {};
try { base = $('Parse Artifacts JSON').item.json || {}; } catch (e) { try { base = $('Classify Request').item.json || {}; } catch (e2) { base = {}; } }
const artifacts = base.artifacts || {};
const actions = parsed || {};
const created = actions.created_artifacts || artifacts.created_artifacts || { google_doc_url: null, sent_email_ids: [], clickup_task_ids: [], calendar_event_ids: [] };
const errors = []
  .concat(Array.isArray(base.errors) ? base.errors : [])
  .concat(Array.isArray((base.extraction || {}).errors) ? base.extraction.errors : [])
  .concat(Array.isArray(artifacts.errors) ? artifacts.errors : [])
  .concat(Array.isArray(actions.errors) ? actions.errors : []);
const status = actions.status || artifacts.status || (base.extraction || {}).status || base.status_hint || 'completed';
return [{ json: {
  status,
  language: actions.language || artifacts.language || (base.extraction || {}).language || base.language || 'es-CR',
  meeting: actions.meeting || artifacts.meeting || (base.extraction || {}).meeting || { title: base.meeting_title, meeting_url: base.meeting_url, meeting_date: base.meeting_date, duration_minutes: null, attendees: [] },
  executive_summary: artifacts.executive_summary || (base.extraction || {}).executive_summary || [],
  decisions: artifacts.decisions || (base.extraction || {}).decisions || [],
  action_items: artifacts.action_items || (base.extraction || {}).action_items || [],
  risks_and_questions: artifacts.risks_and_questions || (base.extraction || {}).risks_and_questions || [],
  created_artifacts: created,
  errors,
  user_message: actions.user_message || artifacts.user_message || (base.extraction || {}).user_message || raw.user_message || '',
  raw_outputs: { intake_or_actions: rawOutput, extraction: base.raw_extraction_output || null, artifacts: base.raw_artifact_output || null }
} }];
